fn solve(n: i8) -> bool {
    // First, exclude the entire forbidden ranges:
    // 12 < n < 30, 69 < n < 80, and n > 89
    if (12 < n && n < 30) || (69 < n && n < 80) || (n > 89) {
        return false;
    }

    // For n < 12, only 1, 7, 9, 10, 11 are false; everything else is true
    if n < 12 {
        return !matches!(n, 1 | 7 | 9 | 10 | 11);
    }

    // For the remaining values (which are exactly 12, 30–69, 80–89),
    // check the last decimal digit
    let d = n % 10;
    !matches!(d, 1 | 7 | 9)
}

